def remove_small_dirs(root_dir, max_size):
    for dirpath, dirnames, filenames in os.walk(root_dir, topdown=False):
        for dirname in dirnames:
            dir_fullpath = os.path.join(dirpath, dirname)
            total_size = sum(os.path.getsize(os.path.join(dir_fullpath, f)) for f in os.listdir(dir_fullpath) if os.path.isfile(os.path.join(dir_fullpath, f)))
            if total_size < max_size:
                print('Removing directory:', dir_fullpath)
                shutil.rmtree(dir_fullpath)
